<?php
namespace App\Services;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Carbon\CarbonImmutable;
use Illuminate\Validation\ValidationException;
final class FinanceReconciliation {
 public function __construct(public FinanceAccess $fin,public SchoolCashFlow $flow){}
 private function query(int $sid,int $campus,string $key,string $day){return DB::table('finance_reconciliations')->where('school_id',$sid)->where('campus_id',$campus)->where('account_key',$key)->where('closing_date',$day);}
 private function key(Request $r,int $campus,?int $bank):string{[$sid]=$this->fin->context($r);$this->fin->campus($r,$campus);if($bank){$b=$this->fin->row('bank_accounts',$sid,$bank);if($b->campus_id===null)$this->fin->fail('School-wide bank accounts appear in cash-flow reports. Daily reconciliation requires a campus-specific account, so a partial campus balance is never presented as a whole bank statement.');if((int)$b->campus_id!==$campus)abort(404);}return $bank?'bank:'.$bank:'cash';}
 private function state(Request $r,int $campus,?int $bank,string $day,string $opening,bool $checkPrior=true):array{[$sid]=$this->fin->context($r);$key=$this->key($r,$campus,$bank);$previousDay=CarbonImmutable::parse($day)->subDay()->toDateString();$prior=$this->query($sid,$campus,$key,$previousDay)->where('status','approved')->orderByDesc('revision')->first();if($prior){if($checkPrior){$cursor=$prior;while($cursor){$old=json_decode($cursor->snapshot,true);$fresh=$this->state($r,$campus,$bank,$cursor->closing_date,$old['opening_balance'],false);if($fresh['source_digest']!==$cursor->source_digest)$this->fin->fail('An earlier daily closing changed. Review a new revision for that date before carrying its balance forward.');$cursor=$fresh['previous_closing_id']?$this->fin->row('finance_reconciliations',$sid,$fresh['previous_closing_id']):null;}}$opening=$prior->counted_balance;}$n=$this->fin->cents($opening,true);if(!$bank&&$n<0)$this->fin->fail('Cash opening balance cannot be negative.');$rows=array_values(array_filter($this->flow->rows($r,[$campus],$day,$day),fn($x)=>$x['account_key']===$key));$totals=$this->flow->totals($rows);$expected=$n+$this->fin->cents($totals['book_net'],true);if(abs($expected)>999999999999)$this->fin->fail('Closing balance exceeds the supported amount.');$state=['campus_id'=>$campus,'bank_account_id'=>$bank,'account_key'=>$key,'closing_date'=>$day,'opening_balance'=>$this->fin->money($n),'expected_balance'=>$this->fin->money($expected),'previous_closing_id'=>$prior?->id,'rows'=>$rows,'totals'=>$totals];$state['source_digest']=hash('sha256',json_encode($state));return $state;}
 public function preview(Request $r,array $d):array{if($d['closing_date']>$this->fin->today())$this->fin->fail('Choose today or an earlier closing date.');return $this->state($r,$d['campus_id'],$d['bank_account_id']??null,$d['closing_date'],$d['opening_balance']);}
 public function submit(Request $r,array $d):array{return DB::transaction(function()use($r,$d){$sid=$this->fin->lock($r,'finance.manage');$this->fin->campus($r,$d['campus_id'],true);$p=$this->preview($r,$d);if($d['source_digest']!==$p['source_digest'])$this->fin->fail('Closing inputs changed. Calculate a fresh preview.');$q=$this->query($sid,$d['campus_id'],$p['account_key'],$d['closing_date']);if((clone $q)->where('status','pending')->exists())$this->fin->fail('A closing revision is already waiting for review.');$counted=$this->fin->cents($d['counted_balance'],true);if(empty($d['bank_account_id'])&&$counted<0)$this->fin->fail('Counted cash cannot be negative.');$approved=(clone $q)->where('status','approved')->orderByDesc('revision')->first();if($approved&&$approved->source_digest===$p['source_digest']&&$this->fin->cents($approved->counted_balance,true)===$counted)$this->fin->fail('This exact closing is already approved.');$variance=$counted-$this->fin->cents($p['expected_balance'],true);$id=DB::table('finance_reconciliations')->insertGetId(['school_id'=>$sid,'campus_id'=>$d['campus_id'],'bank_account_id'=>$d['bank_account_id']??null,'account_key'=>$p['account_key'],'closing_date'=>$d['closing_date'],'revision'=>(int)(clone $q)->max('revision')+1,'opening_balance'=>$p['opening_balance'],'expected_balance'=>$p['expected_balance'],'counted_balance'=>$this->fin->money($counted),'variance'=>$this->fin->money($variance),'reason'=>$d['reason'],'source_digest'=>$p['source_digest'],'snapshot'=>json_encode($p),'status'=>'pending','requested_by'=>$this->fin->access->membership($r)->id,'created_at'=>now(),'updated_at'=>now()]);$this->fin->audit($r,'closing_submitted','finance_reconciliations',$id,['variance'=>$this->fin->money($variance),'previous_approved_id'=>$approved?->id,'reason'=>$d['reason']]);return ['id'=>$id,'message'=>'Daily closing submitted for review.'];});}
 public function listing(Request $r,array $d){[$sid]=$this->fin->context($r);$this->fin->campus($r,$d['campus_id']);$rows=DB::table('finance_reconciliations')->where('school_id',$sid)->where('campus_id',$d['campus_id'])->orderByDesc('closing_date')->orderByDesc('id')->paginate(20,['id','campus_id','account_key','closing_date','revision','status','expected_balance','counted_balance','variance','reason']);return $rows;}
 public function detail(Request $r,int $id):array{[$sid]=$this->fin->context($r);$v=$this->fin->row('finance_reconciliations',$sid,$id);$this->fin->campus($r,$v->campus_id);$v->snapshot=json_decode($v->snapshot,true);$changed=true;$warning=null;try{$p=$this->state($r,$v->campus_id,$v->bank_account_id,$v->closing_date,$v->opening_balance);$changed=$p['source_digest']!==$v->source_digest;}catch(ValidationException $e){$warning=collect($e->errors())->flatten()->first();}$latest=$this->query($sid,$v->campus_id,$v->account_key,$v->closing_date)->where('status','approved')->max('revision');return ['closing'=>$v,'source_changed'=>$changed,'warning'=>$warning,'superseded'=>$v->status==='approved'&&$latest>$v->revision,'school'=>DB::table('schools')->where('id',$sid)->first(['name','code']),'campus'=>$this->fin->row('campuses',$sid,$v->campus_id)];}
 public function review(Request $r,int $id,array $d):array{return DB::transaction(function()use($r,$id,$d){$sid=$this->fin->lock($r,'finance.approve');$v=$this->fin->row('finance_reconciliations',$sid,$id);$this->fin->campus($r,$v->campus_id);if($v->status!=='pending')$this->fin->fail('This closing revision was already reviewed.');if($d['action']==='approve'){$p=$this->state($r,$v->campus_id,$v->bank_account_id,$v->closing_date,$v->opening_balance);if($p['source_digest']!==$v->source_digest)$this->fin->fail('Financial entries changed after submission. Reject this revision and submit a fresh closing.');}DB::table('finance_reconciliations')->where('school_id',$sid)->where('id',$id)->update(['status'=>$d['action']==='approve'?'approved':'rejected','approved_by'=>$this->fin->access->membership($r)->id,'review_note'=>$d['reason'],'reviewed_at'=>now(),'updated_at'=>now()]);$this->fin->audit($r,'closing_'.$d['action'],'finance_reconciliations',$id,['reason'=>$d['reason']]);return ['message'=>'Closing review recorded.'];});}
}
